Object.assign(window.TEM8_DICTIONARY, {"skillful":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/skillful__gb_1.mp3","us":"media/us/skillful__us_1.mp3"},"oxford":{"phon":"ˈskɪlfl","pos":"adjective","senses":[{"en":"good at doing something, especially something that needs a particular ability or special training","cn":"技术好的；功夫深的；熟练的","ex":{"en":"a skillful player/performer/teacher","cn":"熟练的演奏者/表演者/老师"}},{"en":"made or done very well","cn":"制作精良的；处理巧妙的","ex":{"en":"Thanks to her skillful handling of the affair, the problem was averted.","cn":"幸亏她处理得巧妙，问题才得以避免。"}}]}},"skin":{"media":{"img":["media/pic/fruit_comp.jpg","media/thumb/banana.jpg","media/ldoce/img/kiwi.jpg"],"uk":"media/uk/skin__gb_1.mp3","us":"media/us/skin__us_1.mp3"},"oxford":{"phon":"skɪn","pos":"noun","senses":[{"en":"the layer of tissue that covers the body","cn":"皮；皮肤","g":"[uncountable, countable]","lab":"informal","sc":"on body","ex":{"en":"to have dark/pale skin","cn":"皮肤黝黑／苍白"}},{"en":"having the type of skin mentioned","cn":"…皮肤的","sc":"-skinned","ex":{"en":"dark-skinned","cn":"深色皮肤的"}},{"en":"the skin of a dead animal with or without its fur, used for making leather, etc.","cn":"（兽）皮；毛皮；皮张","g":"[countable, uncountable]","sc":"of dead animal","ex":{"en":"The skins are removed and laid out to dry.","cn":"皮剥下来，摊开晾干。"}},{"en":"the outer layer of some fruits and vegetables","cn":"（某些水果和蔬菜的）皮，壳","g":"[countable, uncountable]","sc":"of fruit/vegetables","ex":{"en":"Remove the skins by soaking the tomatoes in hot water.","cn":"把西红柿放在热水里烫一下去皮。"}},{"en":"the thin outer layer of a sausage","cn":"外皮；肠衣","g":"[countable, uncountable]","sc":"of sausage","ex":{"en":"Prick the skins before grilling.","cn":"烤前先在肠衣上扎孔。"}},{"en":"the thin layer that forms on the surface of some liquids, especially when they become cold after being heated","cn":"（尤指加热冷却后形成的）薄层，皮","g":"[countable, uncountable]","sc":"on liquids","ex":{"en":"A skin had formed on the top of the milk.","cn":"奶上结了一层奶皮。"}},{"en":"a layer that covers the outside of something","cn":"外壳；外层","g":"[countable]","sc":"outside layer","ex":{"en":"the outer skin of the earth","cn":"地壳"}},{"en":"a special cover for any small electronic device that you can carry with you","cn":"（便携式电子设备的）护套，保护壳","g":"[countable]","sc":"outside layer","ex":{"en":"Do phone skins protect your phone?","cn":"手机壳能保护你的手机吗？"}},{"en":"the interface of a computer program (= the way a computer program presents information on screen), that the user can change as they wish","cn":"皮肤（电脑程序的用户界面，可按个人喜好变换）","g":"[countable]","lab":"computing","sc":"in a computer program"},{"en":"to take the skin off an animal, a fruit or a vegetable","cn":"剥皮；扒皮；削皮","sc":"animal/fruit/vegetable","ex":{"en":"You'll need four ripe tomatoes, skinned and chopped.","cn":"需要四个成熟了的西红柿，去皮切碎。"},"pos":"verb"},{"en":"to rub the skin off part of your body by accident","cn":"擦破（身体某部位的）皮肤","sc":"part of body","ex":{"en":"He skinned his knees climbing down the tree.","cn":"他从树上爬下来时把膝盖蹭破了。"},"pos":"verb"},{"en":"to change the way that a computer program presents information on the screen to suit your particular needs","cn":"换皮肤（指更改用户界面）","lab":"computing","sc":"part of body","ex":{"en":"The only initial costs the business had were those involved with skinning the website.","cn":"该业务唯一的初始成本是与网站换肤相关的成本。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"皮肤;皮","en":"Your skin is the natural covering of your body.","ex":{"en":"His skin is clear and smooth","cn":"他的皮肤光洁平滑。"}},{"pos":"N-VAR 可变名词","cn":"兽皮;皮毛","en":"An animal skin is skin which has been removed from a dead animal. Skins are used to make things such as coats and rugs.","ex":{"en":"That was real crocodile skin.","cn":"那是真正的鳄鱼皮。"}},{"pos":"N-VAR 可变名词","cn":"果皮;(蔬菜的)表皮","en":"The skin of a fruit or vegetable is its outer layer or covering.","ex":{"en":"The outer skin of the orange is called the 'zest'.","cn":"橙子皮称为 zest。"}},{"pos":"N-SING 单数名词","cn":"(液体表面凝结的)薄皮，薄层","en":"If a skin forms on the surface of a liquid, a thin, fairly solid layer forms on it.","ex":{"en":"Stir the custard occasionally to prevent a skin forming.","cn":"要不时地搅拌牛奶蛋糊，防止其表面结皮。"}},{"pos":"VERB 动词","cn":"剥去(死动物)的皮;将…去皮","en":"If you skin a dead animal, you remove its skin.","ex":{"en":"...with the expertise of a chef skinning a rabbit.","cn":"具有大厨剥兔子皮的娴熟技艺"}},{"pos":"PHRASE 短语","cn":"吓得魂飞魄散;大吃一惊","en":"If something makes you jump out of your skin, it surprises or shocks you very much.","ex":{"en":"He nearly jumped out of his skin when he saw two rats.","cn":"他看到两只老鼠，几乎给吓丢了魂。"}},{"pos":"PHRASE 短语","cn":"保命;保全自己;设法摆脱困境","en":"If you try to save your own skin or save your skin, you try to save yourself from something dangerous or unpleasant.","ex":{"en":"He'd have done anything to anybody to save his own skin.","cn":"为了活命，他可以不顾任何人，不择手段。"}},{"pos":"PHRASE 短语","cn":"侥幸;好不容易才;险些儿没有","en":"If you do something by the skin of your teeth, you just manage to do it.","ex":{"en":"He won, but only by the skin of his teeth.","cn":"他赢了，但是赢得十分勉强。"}},{"pos":"PHRASE 短语","cn":"脸皮厚;不计较面子","en":"If you say that someone has a thick skin, you mean that they are able to listen to criticism about themselves without becoming offended.","ex":{"en":"You need a thick skin to be a headmaster.","cn":"要当校长，你就得脸皮厚一些。"}},{"pos":"","cn":"","en":"to make your skin crawl→see: ;"}]},"examples":[{"en":"You can create your own custom skin for your iPod.","cn":"你可以为你的 iPod 制作个性化护套。"},{"en":"You'll need four ripe tomatoes, skinned and chopped.","cn":"需要四个熟了的西红柿，去皮切碎。"}]},"ski":{"oxford":{"phon":"skiː","pos":"noun","senses":[{"en":"one of a pair of long narrow pieces of wood, metal or plastic that you attach to boots so that you can move smoothly over snow","cn":"滑雪板","ex":{"en":"a pair of skis","cn":"一副滑雪板"}},{"en":"either of the pair of long flat boards on which a person stands in order to waterski","cn":"滑水橇"},{"en":"connected with the sport of skiing","cn":"滑雪的","ex":{"en":"a ski resort","cn":"滑雪胜地"},"pos":"adjective"},{"en":"to move over snow on skis, especially as a sport","cn":"滑雪（运动）","g":"[intransitive]","ex":{"en":"Our children want to learn to ski.","cn":"我们的孩子们想学滑雪。"},"pos":"verb"},{"en":"to spend time skiing for pleasure","cn":"滑雪（作为娱乐）","g":"[intransitive]","ex":{"en":"We went skiing in France in March.","cn":"三月份我们去法国滑雪了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"滑雪板;滑水板","en":"Skis are long, flat, narrow pieces of wood, metal, or plastic that are fastened to boots so that you can move easily on snow or water.","ex":{"en":"...a pair of skis.","cn":"一副滑雪板"}},{"pos":"VERB 动词","cn":"滑雪;滑水","en":"When people ski, they move over snow or water on skis.","ex":{"en":"They surf, ski and ride","cn":"他们冲浪，滑雪，还骑马。"}},{"pos":"ADJ 形容词","cn":"滑雪用的;滑雪的;滑水的","en":"You use ski to refer to things that are concerned with skiing.","ex":{"en":"...the Swiss ski resort of Klosters.","cn":"瑞士克洛斯特斯滑雪胜地"}}]},"media":{"img":["media/pic/wintersports_comp.jpg","media/thumb/downhillskiing.jpg","media/ldoce/img/skiing.jpg","media/ldoce/img/skiing.jpg"],"uk":"media/uk/ski__gb_1.mp3","us":"media/us/ski__us_1.mp3"},"examples":[{"en":"We went skiing in France in March.","cn":"三月份我们去法国滑雪了。"},{"en":"a pair of skis","cn":"一副滑雪板"}]},"sky":{"media":{"uk":"media/uk/sky__gb_1.mp3","us":"media/us/sky__us_1.mp3"},"oxford":{"phon":"skaɪ","pos":"noun","senses":[{"en":"the space above the earth that you can see when you look up, where clouds and the sun, moon and stars appear","cn":"天；天空","lab":"North American English","ex":{"en":"The sky suddenly went dark and it started to rain.","cn":"天空骤然转暗，随即下起雨来。"}},{"en":"to hit a ball very high into the air","cn":"把（球）击向高空","ex":{"en":"She skied her tee shot.","cn":"她开球那一杆打了一个高空球。"},"pos":"verb"},{"en":"Sky TV was Britain's first satellite television company, owned by Rupert Murdoch. It began broadcasting in 1989 but combined with another company the following year and changed its name to BSkyB (British Sky Broadcasting). It later became Sky UK. It uses the name Sky in several digital television channels, which can only be seen by people who pay a fee each month. Most of the channels broadcast one particular type of programme and have names like Sky Sports, Sky Movies or Sky Arts. Sky also provides internet and mobile phone services.","cn":"天空：天空电视台是鲁珀特·默多克（Rupert Murdoch）拥有的英国第一家卫星电视公司。它于1989年开始广播，但于次年与另一家公司合并，并更名为BSkyB（英国天空广播）。后来它成为了Sky UK。它在几个数字电视频道中使用“天空”这个名字，只有每月付费的人才能看到。大多数频道播放一种特定类型的节目，并以天空体育，天空电影或天空艺术之类的名称命名。Sky还提供互联网和手机服务。","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"天;天空","en":"The sky is the space around the earth which you can see when you stand outside and look upwards.","ex":{"en":"The sun is already high in the sky.","cn":"已经日上三竿。"}},{"pos":"","cn":"","en":"pie in the sky→see: ;"}]},"examples":[{"en":"The sky suddenly went dark and it started to rain.","cn":"天空骤然转暗，随即下起雨来。"},{"en":"The skies above London were ablaze with a spectacular firework display.","cn":"伦敦上空烟火绽放，景象壮观。"}]},"skilled":{"media":{"uk":"media/uk/skilled__gb_1.mp3","us":"media/us/skilled__us_1.mp3"},"oxford":{"phon":"skɪld","pos":"adjective","senses":[{"en":"having enough ability, experience and knowledge to be able to do something well","cn":"有技能的；熟练的","ex":{"en":"a skilled engineer/negotiator/craftsman","cn":"高明的工程师；老练的谈判者；技术熟练的工匠"}},{"en":"needing special abilities or training","cn":"需要专门技术的","ex":{"en":"Furniture-making is very skilled work.","cn":"做家具是技术性很强的活儿。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有技术的;有技能的;熟练的","en":"Someone who is skilled has the knowledge and ability to do something well.","ex":{"en":"Not all doctors are skilled in helping their patients make choices.","cn":"并非所有医生都善于帮助病人作出正确选择。"}},{"pos":"ADJ 形容词","cn":"需要熟练技术的;需要专门技能的","en":"Skilled work can only be done by people who have had some training.","ex":{"en":"New industries demanded skilled labour not available locally.","cn":"新行业所需的技术工人在当地是找不到的。"}}]},"examples":[{"en":"She is highly skilled at dealing with difficult customers.","cn":"应付难缠的顾客她很有一手。"},{"en":"Furniture-making is very skilled work.","cn":"做家具是技术性很强的活儿。"}]},"skirt":{"media":{"img":["media/pic/clothes_suit_comp.jpg","media/thumb/skirt.jpg"],"uk":"media/uk/skirt__gb_1.mp3","us":"media/us/skirt__us_1.mp3"},"oxford":{"phon":"skɜːt","pos":"noun","senses":[{"en":"a piece of clothing that hangs from the middle part of the body","cn":"女裙；裙子","g":"[countable]","ex":{"en":"a short/long/pleated/denim skirt","cn":"短裙；长裙；百褶裙；牛仔裙"}},{"en":"the part of a dress, coat, etc. that hangs below the middle part of the body","cn":"（连衣裙、外衣等的）下摆","g":"[countable]","ex":{"en":"She tucked up her voluminous skirts to make room for Jane beside her.","cn":"她掖起膨松的裙边给旁边的简腾出地方。"}},{"en":"an outer layer that covers and protects the base of a vehicle or machine","cn":"（车辆或机器基座的）挡板，裙板","g":"[countable]","ex":{"en":"the rubber skirt around the bottom of a hovercraft","cn":"气垫船底部四周的橡胶挡板"}},{"en":"to be or go around the edge of something","cn":"环绕…的四周；位于…的边缘；沿…的边缘走","g":"[transitive, intransitive]","ex":{"en":"They followed the road that skirted the lake.","cn":"他们顺着湖边公路走。"},"pos":"verb"},{"en":"to avoid talking about a subject, especially because it is difficult or embarrassing","cn":"绕开，回避（话题）","g":"[transitive, intransitive]","ex":{"en":"He carefully skirted the issue of where they would live.","cn":"他小心地避开了他们将住在何处这个问题。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"裙子;短裙","en":"A skirt is a piece of clothing worn by women and girls. It fastens at the waist and hangs down around the legs."},{"pos":"VERB 动词","cn":"位于…的边缘;位于…的外围;围绕","en":"Something that skirts an area is situated around the edge of it.","ex":{"en":"We raced across a large field that skirted the slope of a hill.","cn":"我们从山坡下的一大片田地里飞奔而过。"}},{"pos":"VERB 动词","cn":"沿着…的边缘走;沿着…的外围走;绕着…走","en":"If you skirt something, you go around the edge of it.","ex":{"en":"We shall be skirting the island on our way","cn":"我们将一路环岛而行。"}},{"pos":"VERB 动词","cn":"避开，回避(困难、问题等)","en":"If you skirt a problem or question, you avoid dealing with it.","ex":{"en":"He skirted the hardest issues, concentrating on areas of possible agreement","cn":"他避开了最棘手的问题，将精力集中于有可能达成一致的领域。"}}]},"examples":[{"en":"He carefully skirted the issue of where they would live.","cn":"他小心地避开了他们将住在何处这个问题。"},{"en":"I skirted around the field and crossed the bridge.","cn":"我沿着田边走，又绕过了那座桥。"}]},"skies":{"lemma":"sky","media":{"uk":"media/uk/skies__gb_1.mp3","us":"media/us/skies__us_1.mp3"}},"skins":{"lemma":"skin","media":{"img":["media/pic/fruit_comp.jpg","media/thumb/banana.jpg"],"uk":"media/uk/skin__gb_1.mp3","us":"media/us/skin__us_1.mp3"}},"skate":{"oxford":{"phon":"skeɪt","pos":"verb","senses":[{"en":"to move on skates (usually referring to ice skating, if no other information is given)","cn":"（通常指）滑冰，溜冰","g":"[intransitive, transitive]","ex":{"en":"Can you skate?","cn":"你会滑冰吗？"}},{"en":"to ride on a skateboard","cn":"滑（滑板）","g":"[intransitive]"},{"en":"a boot with a thin metal blade (= sharp edge) on the bottom, that is used for skating on ice","cn":"冰鞋；溜冰鞋","ex":{"en":"a pair of skates","cn":"一双冰鞋"},"pos":"noun"},{"en":"a type of boot with two pairs of small wheels attached to the bottom","cn":"（四轮）旱冰鞋；滚轴溜冰鞋；轮式溜冰鞋","pos":"noun"},{"en":"a large flat sea fish that can be eaten","cn":"鳐（扁体鱼，可食用）","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"冰鞋;溜冰鞋","en":"Skates are ice-skates."},{"pos":"N-COUNT 可数名词","cn":"四轮溜冰鞋;旱冰鞋","en":"Skates are roller-skates."},{"pos":"VERB 动词","cn":"溜冰;滑冰","en":"If you skate, you move about wearing ice-skates or roller-skates.","ex":{"en":"I actually skated, and despite some teetering I did not fall on the ice","cn":"我真的滑冰了——尽管有些踉跄，但没有跌跟头。"}},{"pos":"N-COUNT 可数名词","cn":"鳐鱼(一种扁平状海鱼)","en":"A skate is a kind of flat sea fish.","ex":{"en":"Boats had plenty of mackerel and a few skate.","cn":"那些船上有许多鲭鱼，还有几条鳐鱼。"}},{"pos":"VERB 动词","cn":"避谈;回避;搪塞","en":"If you skate over or round a difficult subject, you avoid discussing it.","ex":{"en":"Scientists have tended to skate over the difficulties of explaining dreams","cn":"科学家们往往回避释梦的难题。"}}]},"media":{"uk":"media/uk/skate__gb_1.mp3","us":"media/us/skate__us_1.mp3"},"examples":[{"en":"He skated an exciting programme at the American Championships.","cn":"他在美国锦标赛上滑出一组扣人心弦的动作。"},{"en":"It was so cold that we were able to go skating on the lake.","cn":"天气极冷，我们能到湖上去滑冰了。"}]},"skill":{"media":{"uk":"media/uk/skill__gb_1.mp3","us":"media/us/skill__us_1.mp3"},"oxford":{"phon":"skɪl","pos":"noun","senses":[{"en":"the ability to do something well","cn":"技巧；技艺","g":"[uncountable]","ex":{"en":"The job requires skill and an eye for detail.","cn":"这项工作需要技巧和敏锐的眼光。"}},{"en":"a particular ability or type of ability","cn":"技术；技能","g":"[countable]","ex":{"en":"communication/language/leadership skills","cn":"交流／语言／领导能力"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"技术性工作;手艺","en":"A skill is a type of work or activity which requires special training and knowledge.","ex":{"en":"Most of us will know someone who is always learning new skills, or studying new fields.","cn":"我们大多数人都会认识某个总是在不停地学习新技术或研究新领域的人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"技巧;技能;本领;技艺","en":"Skill is the knowledge and ability that enables you to do something well.","ex":{"en":"The cut of a diamond depends on the skill of its craftsman.","cn":"钻石切割靠的是工匠的技艺。"}}]},"examples":[{"en":"What made him remarkable as a photographer was his skill in capturing the moment.","cn":"他捕捉瞬间画面的能力使他成为一名不同凡响的摄影师。"},{"en":"The job requires skill and an eye for detail.","cn":"这项工作需要技巧和敏锐的眼光。"}]},"skilful":{"oxford":{"phon":"ˈskɪlfl","pos":"adjective","senses":[{"en":"good at doing something, especially something that needs a particular ability or special training","cn":"技术好的；功夫深的；熟练的","ex":{"en":"a skilful player/performer/teacher","cn":"技术好的运动员；功夫深的表演者；会教学的老师"}},{"en":"made or done very well","cn":"制作精良的；处理巧妙的","ex":{"en":"Thanks to her skilful handling of the affair, the problem was averted.","cn":"多亏她对事情处理得巧妙，才避免了麻烦。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有技巧的;熟练的;巧妙的","en":"Someone who is skilful at something does it very well.","ex":{"en":"He is widely regarded as Hungary's most skilful politician.","cn":"他是公认的匈牙利最有手腕的政治家。"}}]},"media":{"uk":"media/uk/skilful__gb_1.mp3","us":"media/us/skilful__us_1.mp3"},"examples":[{"en":"Thanks to her skilful handling of the affair, the problem was averted.","cn":"多亏她对事情处理得巧妙，才避免了麻烦。"},{"en":"a skilful player/performer/teacher","cn":"技术好的运动员；功夫深的表演者；会教学的老师"}]},"skilfully":{"oxford":{"phon":"ˈskɪlfəli","pos":"adverb","senses":[{"en":"in a way that shows skill","cn":"有技巧地","ex":{"en":"a skilfully crafted novel","cn":"一部精心制作的小说"}}]},"media":{"uk":"media/uk/skilfully__gb_1.mp3","us":"media/us/skilfully__us_1.mp3"},"examples":[{"en":"After a few years, he became very skilful at drawing.","cn":""},{"en":"the skilful use of sound effects","cn":""}]},"ska":{"oxford":{"phon":"skɑː","pos":"noun","senses":[{"en":"a type of fast popular music with strong rhythms, developed in Jamaica in the 1960s and that developed into reggae","cn":"斯卡（20 世纪 60 年代兴起于牙买加的一种节奏强而快的流行音乐，后来发展成雷鬼乐）"}]},"media":{"uk":"media/uk/ska__gb_1.mp3","us":"media/us/ska__us_1.mp3"}},"skeleton":{"oxford":{"phon":"ˈskelɪtn","pos":"noun","senses":[{"en":"the structure of bones that supports the body of a person or an animal; a model of this structure","cn":"骨骼；骨架；骨骼标本","g":"[countable]","ex":{"en":"The human skeleton consists of 206 bones.","cn":"人的骨骼由 206 块骨头组成。"}},{"en":"a very thin person or animal","cn":"骨瘦如柴的人（或动物）","g":"[countable]","lab":"informal","ex":{"en":"The disease has reduced her to a skeleton.","cn":"疾病使她只剩下一副骷髅。"}},{"en":"the main structure that supports a building, etc.","cn":"（建筑物等的）骨架，框架","g":"[countable, usually singular]","ex":{"en":"Only the concrete skeleton of the factory remained.","cn":"厂房只剩下混凝土骨架了。"}},{"en":"the basic outline of a plan, piece of writing, etc. to which more details can be added later","cn":"梗概；提纲；提要；轮廓","g":"[countable, usually singular]","ex":{"en":"Examples were used to flesh out the skeleton of the argument.","cn":"通过例证使干巴巴的论点充实起来。"}},{"en":"the smallest number of people, etc. that you need to do something","cn":"（维持运转所需的）最少人员，基干人员","g":"[singular]","ex":{"en":"There will only be a skeleton staff on duty over the holiday.","cn":"假期将只留必需的少数职员值班。"}},{"en":"a type of sledge (= a vehicle for sliding over ice) for racing, used by one person lying on their front with their feet pointing backwards","cn":"（一种单人比赛用的）钢架雪车，俯式冰橇","g":"[countable]","lab":"sport","ex":{"en":"It’s just like the skeletons they use in the Olympics.","cn":"就像他们在奥运会上使用的骷髅一样。"}},{"en":"the sport or event of racing down a special track of ice on a skeleton (6)","cn":"钢架雪车运动；俯式冰橇运动","g":"[uncountable]","ex":{"en":"Canada won gold and silver in the skeleton.","cn":"加拿大选手在钢架雪车项目中包揽金银牌。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"骨骼;骸骨","en":"Your skeleton is the framework of bones in your body.","ex":{"en":"...a human skeleton.","cn":"人体骨骼"}},{"pos":"ADJ 形容词","cn":"(员工)最基本的，基干的","en":"A skeleton staff is the smallest number of staff necessary in order to run an organization or service.","ex":{"en":"Only a skeleton staff remains to show anyone interested around the site.","cn":"只有一小部分必需的工作人员留在那里，带有兴趣的人参观遗址。"}},{"pos":"N-COUNT 可数名词","cn":"轮廓;框架;构架;梗概","en":"The skeleton of something such as a building or a plan is its basic framework.","ex":{"en":"Only skeletons of buildings remained.","cn":"只剩下了建筑物的框架。"}},{"pos":"PHRASE 短语","cn":"家丑;不可告人的丑事","en":"If you say that someone has a skeleton in the closet, or in British English a skeleton in the cupboard, you mean that they are keeping secret a bad or embarrassing fact about themselves.","ex":{"en":"Mr Worthing is this election's Mr Nice Guy, without any skeletons in his cupboard.","cn":"沃辛先生是此次选举中的正派先生，本身没有任何见不得人的丑事。"}}]},"media":{"img":["media/ldoce/img/skeleton.jpg","media/pic/skeleton_body_comp.jpg"],"uk":"media/uk/skeleton__gb_1.mp3","us":"media/us/skeleton__us_1.mp3"},"examples":[{"en":"We managed to operate a skeleton bus service during the strike.","cn":"罢工期间，我们设法保持最起码的公共汽车营运。"},{"en":"Canada won gold and silver in the skeleton.","cn":"加拿大选手在俯式冰橇项目中包揽金银牌。"}]},"skeptical":{"media":{"uk":"media/uk/sceptical__gb_1.mp3","us":"media/us/sceptical__us_1.mp3"},"oxford":{"phon":"ˈskeptɪkl","pos":"adjective","senses":[{"en":"having doubts that a claim or statement is true or that something will happen","cn":"怀疑的","ex":{"en":"I am skeptical about his chances of winning.","cn":"我怀疑他取胜的可能性。"}}]},"examples":[{"en":"The public remain skeptical of these claims.","cn":"公众对这些说法仍持怀疑态度。"},{"en":"I am skeptical about his chances of winning.","cn":"我怀疑他获胜的可能性。"}],"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"skeptically":{"oxford":{"phon":"ˈskeptɪkli","pos":"adverb","senses":[{"en":"in a way that shows doubts that a claim or statement is true or that something will happen","cn":"怀疑的","ex":{"en":"The announcement was greeted skeptically by the press.","cn":"媒体对这一消息表示怀疑。"}}]},"media":{"uk":"media/uk/sceptically__gb_1.mp3","us":"media/us/sceptically__us_1.mp3"}},"skills":{"lemma":"skill"},"skateboarding":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"滑板运动","en":"Skateboarding is the activity of riding on a skateboard."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short board with two small wheels at each end, which you can stand on and ride for fun or as a sport","cn":""}]},"media":{"img":["media/ldoce/img/skateboard.jpg","media/thumb/skateboarding.jpg"],"uk":"media/ldoce/hwd/bre/f/skateboard0205.mp3","us":"media/ldoce/hwd/ame/c/skateboard.mp3"},"examples":[{"en":"a skateboarding magazine","cn":"滑板运动杂志"}],"oxford":{"phon":"ˈskeɪtbɔːdɪŋ","pos":"noun","senses":[{"en":"the sport or activity of riding on a skateboard","cn":"滑冰；溜冰","ex":{"en":"a skateboarding magazine","cn":"滑板运动杂志"}}]},"base":"skateboard"},"skyscraper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"摩天大楼;摩天大厦","en":"A skyscraper is a very tall building in a city."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"measuring a long distance from top to bottom - use this about mountains, walls, or buildings","cn":""},{"en":"high and narrow or long - use this about trees and plants or about buildings and parts of buildings","cn":""},{"en":"very high especially in a way that seems frightening or impressive","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A skyscraper is a very tall building, like New York City's Empire State Building, which held the title of \"World's Tallest Building\" for many years."}]},"collocations":{"phrases":["ADJ. towering","SKYSCRAPER + VERB loom, rise On all sides, skyscrapers rose like jagged teeth.","SKYSCRAPER + NOUN block"]},"media":{"img":["media/ldoce/img/skyscraper.jpg","media/thumb/skyscraper.jpg"],"uk":"media/ldoce/hwd/bre/f/skyscraper0205.mp3","us":"media/ldoce/hwd/ame/b/skyscraper.mp3"},"oxford":{"phon":"ˈskaɪskreɪpə(r)","pos":"noun","senses":[{"en":"a very tall building in a city","cn":"摩天大楼","ex":{"en":"the world's tallest skyscraper","cn":"世界最高的摩天楼"}}]}},"skillet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"平底煎锅","en":"A skillet is a shallow iron pan which is used for frying."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flat heavy cooking pan with a long handle","cn":"长柄平底煎锅"}]},"media":{"img":["media/ldoce/img/frying_pan.jpg"],"uk":"media/ldoce/hwd/bre/8/skillet0205.mp3","us":"media/ldoce/hwd/ame/a/skillet.mp3"},"oxford":{"phon":"ˈskɪlɪt","pos":"noun","senses":[{"en":"a large shallow pan with a long handle, used for frying food in","cn":"长柄平底煎锅","ex":{"en":"Place the skillet over medium heat.","cn":"把锅放在中火上。"}}]}},"skew":{"collins":{"senses":[{"pos":"VERB 动词","cn":"影响…的准确性;歪曲;扭曲","en":"If something is skewed, it is changed or affected to some extent by a new or unusual factor, and so is not correct or normal.","ex":{"en":"The arithmetic of nuclear running costs has been skewed by the fall in the cost of other fuels","cn":"核运营成本的计算由于其他燃料的降价而出现了偏差。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something skews the results of a test etc, it affects them, making them incorrect","cn":"影响〔测试结果等〕的准确性﹐使偏颇"},{"en":"to affect or influence someone’s ideas, actions, or judgment, especially in a way that makes the ideas etc not correct or fair","cn":"使曲解﹐使存有偏见"}]},"vocab":{"pos":"v adj","senses":[{"en":"To skew is to turn or place at an angle. When you build a house of cards, you must slightly angle, or skew each card, so structure will stand up."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41skew.mp3","us":"media/ldoce/hwd/ame/9/skew1.mp3"},"examples":[{"en":"The ball skewed off at a right angle.","cn":"球呈直角偏离弹了出去。"},{"en":"to skew the statistics","cn":"影响统计数字的准确性"}],"oxford":{"phon":"skjuː","pos":"verb","senses":[{"en":"to change or influence something with the result that it is not accurate, fair, normal, etc.","cn":"歪曲；曲解；使不公允；影响…的准确性","g":"[transitive]","ex":{"en":"to skew the statistics","cn":"影响统计数字的准确性"}},{"en":"to move or lie at an angle, especially in a position that is not normal","cn":"偏离；歪斜","g":"[intransitive]","lab":"British English","ex":{"en":"The ball skewed off at a right angle.","cn":"球呈直角偏离弹了出去。"}}]}},"skipper":{"collins":{"senses":[{"pos":"N-COUNT; N-VOC 可数名词；称呼名词","cn":"船长","en":"You can use skipper to refer to the captain of a ship or boat.","ex":{"en":"...the skipper of an English fishing boat","cn":"一艘英国渔船的船长"}},{"pos":"N-COUNT 可数名词","cn":"(体育运动队的)队长","en":"You can use skipper to refer to the captain of a sports team.","ex":{"en":"The England skipper is confident.","cn":"英格兰队的队长信心十足。"}},{"pos":"VERB 动词","cn":"当…的队长(或船长)","en":"To skipper a team or a boat means to be the captain of it.","ex":{"en":"He skippered the second Rugby XV","cn":"他担任了橄榄球 15 人联队的第二任队长。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the person in charge of a ship","cn":"船长"},{"en":"the leader of a sports team 〔","cn":"运动队的〕队长"},{"en":"to be in charge of a ship, sports team etc – used especially in news reports","cn":"当〔船〕的船长﹔当〔运动队等〕的队长〔尤用于新闻报道〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/skipper_n0205.mp3","us":"media/ldoce/hwd/ame/b/skipper1.mp3"},"examples":[{"en":"( especially BrE ) He skippered the team to victory.","cn":"他率领队伍取得了胜利。"},{"en":"He skippered the team to victory.","cn":""}],"oxford":{"phon":"ˈskɪpə(r)","pos":"noun","senses":[{"en":"the captain of a small ship or fishing boat","cn":"（小船或渔船的）船长"},{"en":"the captain of a sports team","cn":"（运动队的）队长","lab":"informal, especially British English，，"},{"en":"to be the captain of a boat, sports team, etc.","cn":"当船长（或运动队队长等）","lab":"especially British English","ex":{"en":"to skipper a yacht","cn":"当帆船船长"},"pos":"verb"}]}},"skim":{"collins":{"senses":[{"pos":"VERB 动词","cn":"撇去(液体上的漂浮物)","en":"If you skim something from the surface of a liquid, you remove it.","ex":{"en":"Rough seas today prevented specially equipped ships from skimming oil off the water's surface","cn":"今天海面上风浪很大，那些配有专门设备的船只无法展开清除海面浮油的工作。"}},{"pos":"VERB 动词","cn":"掠过;擦过;滑过","en":"If something skims a surface, it moves quickly along just above it.","ex":{"en":"...seagulls skimming the waves","cn":"掠过浪尖的海鸥"}},{"pos":"VERB 动词","cn":"略读;浏览","en":"If you skim a piece of writing, you read through it quickly.","ex":{"en":"He skimmed the pages quickly, then read them again more carefully","cn":"他先快速地浏览页面，然后再细细阅读。"}},{"pos":"","cn":"","en":"相关词组：skim off"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to read something quickly so that you get a general idea of what it is about","cn":""},{"en":"to read something quickly in order to find a particular piece of information","cn":""},{"en":"to read something quickly to check that there are no mistakes or problems","cn":""}]},"vocab":{"pos":"1 v n adj 2 v n 3 v","senses":[{"en":"To skim is to remove something from the surface of a liquid. Some cooks skim the fat off of the top of their chicken noodle soup, others skim the cream off milk to make skim (or skimmed ) milk."}]},"collocations":{"phrases":["ADV. barely (figurative) This report has barely skimmed the surface of the subject. | low A bird skimmed low over the heather.","PREP. across/over We skimmed across the water in a small sailing boat."]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeskim.mp3","us":"media/ldoce/hwd/ame/d/skim.mp3"},"examples":[{"en":"I always skim the financial section of the newspaper.","cn":"我总要浏览一下报纸上的金融版。"},{"en":"Skim the scum off the jam and let it cool.","cn":"撇去果酱上的浮沫，让它冷却。"}],"oxford":{"phon":"skɪm","pos":"verb","senses":[{"en":"to remove fat, cream, etc. from the surface of a liquid","cn":"撇去（液体上的油脂或乳脂等）","g":"[transitive]","ex":{"en":"Skim the scum off the jam and let it cool.","cn":"撇去果酱上的浮沫，让它冷却。"}},{"en":"to move quickly and lightly over a surface, not touching it or only touching it occasionally; to make something do this","cn":"（使）掠过，擦过，滑过","g":"[intransitive, transitive, no passive]","lab":"figurative","ex":{"en":"We watched the birds skimming over the lake.","cn":"我们看着鸟儿贴着湖面飞过。"}},{"en":"to read something quickly in order to find a particular point or the main points","cn":"浏览；略读","g":"[intransitive, transitive]","ex":{"en":"He skimmed through the article trying to find his name.","cn":"他浏览文章寻找自己的名字。"}},{"en":"to steal small amounts of money frequently over a period of time","cn":"惯偷（小数额的钱）","g":"[transitive]","lab":"informal","ex":{"en":"She’d been skimming money from the store’s accounts for years.","cn":"她多年来一直从商店的账上一点一点地窃取金钱。"}},{"en":"to illegally copy electronic information from a credit card in order to use it without the owner’s permission","cn":"盗用（信用卡电子信息）","g":"[intransitive, transitive]","ex":{"en":"It is estimated that skimming now accounts for almost 50% of credit card fraud.","cn":"据估计，目前信用卡诈骗中近 50% 是由盗读造成的。"}}]}},"skive":{"collins":{"senses":[{"pos":"VERB 动词","cn":"逃避工作;(尤指)离开工作岗位，溜号","en":"If you skive, you avoid working, especially by staying away from the place where you should be working.","ex":{"en":"The company treated me as though I were skiving.","cn":"公司对待我的态度就好像是我上班时溜号了似的。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to deliberately not go to school, work etc, when you should be there","cn":""},{"en":"if a child plays truant or plays hooky from school, they deliberately stay away from school without their parent's permission","cn":""},{"en":"if a student cuts classes, school etc, they deliberately do not go to the classes that they should go to","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/skive0205.mp3","us":"media/ldoce/hwd/ame/b/ld41skive.mp3"},"examples":[{"en":"‘Where's Tom?’ ‘Skiving as usual.’ “","cn":"汤姆去哪了？” “和往常一样，溜了。”"},{"en":"She always skives off early on Fridays.","cn":"每到星期五，她总是早早就溜了。"}],"oxford":{"phon":"skaɪv","pos":"verb","senses":[{"en":"to avoid work or school by staying away or leaving early","cn":"躲避（工作）；逃（学）","ex":{"en":"‘Where's Tom?’ ‘Skiving as usual.’","cn":"“汤姆去哪了？”“和往常一样，溜了。”"}}]}},"skimpy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"短小的;少量的","en":"Something that is skimpy is too small in size or quantity.","ex":{"en":"...skimpy underwear","cn":"太过暴露的内衣"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a skimpy dress or skirt etc is very short and does not cover very much of a woman’s body 〔","cn":"衣﹑裙等〕太短[小]的﹐暴露的"},{"en":"not enough of something","cn":"不足的﹐不够的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/skimpy0205.mp3","us":"media/ldoce/hwd/ame/f/skimpy.mp3"},"examples":[{"en":"They provided only skimpy details.","cn":"他们提供的细节不充分。"},{"en":"a skimpy dress","cn":"短而暴露的连衣裙"}],"oxford":{"phon":"ˈskɪmpi","pos":"adjective","senses":[{"en":"very small and not covering much of your body","cn":"小而暴露的","ex":{"en":"a skimpy dress","cn":"短而暴露的连衣裙"}},{"en":"not large enough in amount or size","cn":"（数量或大小）不足的，不够的","lab":"disapproving","ex":{"en":"a skimpy meal","cn":"吃不饱的一顿饭"}}]}},"skinhead":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"剃光头的年轻人;(通常指有暴力行为和攻击性的)光头仔","en":"A skinhead is a young person whose hair is shaved or cut very short. Skinheads are usually regarded as violent and aggressive."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a young white person who has hair that is cut very short, especially one who behaves violently towards people of other races","cn":"光头仔〔尤指对其他种族行为暴虐的白人青年〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/skinhead0205.mp3","us":"media/ldoce/hwd/ame/d/skinhead.mp3"},"oxford":{"phon":"ˈskɪnhed","pos":"noun","senses":[{"en":"a young person with very short hair, especially one who is violent, aggressive and racist","cn":"光头仔（尤指暴虐、好斗的青年种族主义者）"}]}},"skinny":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很瘦的;皮包骨头的;骨瘦如柴的","en":"A skinny person is extremely thin, often in a way that you find unattractive.","ex":{"en":"He was quite a skinny little boy","cn":"他是个瘦得皮包骨头的小男孩。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having little fat on your body","cn":""},{"en":"thin in an attractive way","cn":""},{"en":"thin in an attractive and graceful way – used especially about parts of the body, and used especially about women","cn":""}]},"collocations":{"phrases":["VERBS be, look | become","ADV. really, terribly, very | a bit, fairly, rather At school I was fairly skinny and undersized."]},"media":{"uk":"media/ldoce/hwd/bre/6/skinny0205.mp3","us":"media/ldoce/hwd/ame/1/skinny.mp3"},"examples":[{"en":"This book gives you the skinny on Hollywood.","cn":"这本书披露了好莱坞的内幕。"},{"en":"a skinny latte","cn":"低脂肪的热奶沫咖啡"}],"oxford":{"phon":"ˈskɪni","pos":"adjective","senses":[{"en":"very thin, especially in a way that you find unpleasant or ugly","cn":"极瘦的；干瘦的；皮包骨的","lab":"informal, usually disapproving，，","ex":{"en":"skinny legs","cn":"干瘦的腿"}},{"en":"designed to fit closely to the body","cn":"紧身的","ex":{"en":"skinny jeans","cn":"紧身牛仔裤"}},{"en":"low in fat","cn":"低脂肪的","lab":"informal","ex":{"en":"a skinny latte","cn":"脱脂拿铁咖啡"}},{"en":"information about somebody/something, especially details that are not generally known","cn":"（不公开的）信息；内幕消息","ex":{"en":"So what’s the skinny?","cn":"那么什么是瘦呢？"},"pos":"noun"}]}},"skiff":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(常指单人的)小艇，小船","en":"A skiff is a small light rowing boat or sailing boat, which usually has room for only one person."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small light boat for one person 〔","cn":"单人的〕小艇﹐轻舟"}]},"vocab":{"pos":"n","senses":[{"en":"A skiff is a small boat. If you decide to purchase a skiff instead of giant yacht, you're probably someone who prefers the quiet, simple life. (Or maybe you just didn’t want to spend the money on a yacht.)"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41skiff.mp3","us":"media/ldoce/hwd/ame/8/skiff.mp3"},"oxford":{"phon":"skɪf","pos":"noun","senses":[{"en":"a small light boat for rowing or sailing, usually for one person","cn":"（通常指单人的）小划艇，小帆船"}]}},"skintight":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(衣服)紧身的","en":"Skin-tight clothes fit very tightly so that they show the shape of your body.","ex":{"en":"...the youth with the slicked down hair and skin-tight trousers.","cn":"头发油光发亮、穿着紧身裤的年轻人"}}]},"oxford":{"phon":"ˌskɪnˈtaɪt","pos":"adjective","senses":[{"en":"fitting very closely to the body","cn":"紧身的","ex":{"en":"a skintight dress","cn":"紧身连衣裙"}}]}},"skunk":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"臭鼬","en":"A skunk is a small black and white animal which releases an unpleasant smelling liquid if it is frightened or attacked. Skunks live in America."},{"pos":"N-UNCOUNT 不可数名词","cn":"超劲大麻;强效大麻","en":"Skunk is a type of powerful, strong-smelling marijuana."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small black and white North American animal that produces a strong unpleasant smell if it is attacked or afraid","cn":"臭鼬〔分布于北美洲〕"},{"en":"a very strong type of marijuana","cn":"超劲大麻﹐强效大麻"}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdeskunk.mp3","us":"media/ldoce/hwd/ame/8/skunk.mp3"},"oxford":{"phon":"skʌŋk","pos":"noun","senses":[{"en":"a small black and white North American animal that can produce a strong unpleasant smell to defend itself when it is attacked","cn":"北美臭鼬","g":"[countable]"},{"en":"skunkweed (= a strong type of cannabis)","cn":"烂醉如泥","g":"[uncountable]","lab":"slang"}]}},"skein":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指羊毛或丝线的)一束，一绞","en":"A skein is a length of thread, especially wool or silk, wound loosely round on itself.","ex":{"en":"...a skein of wool.","cn":"一束羊毛"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long loosely wound piece of thread, wool, or yarn 〔","cn":"线﹑毛线或纱的〕一束﹐一绞"},{"en":"a complicated series of things that are related to each other 〔","cn":"错综复杂的〕一系列﹐一连串"}]},"vocab":{"pos":"n","senses":[{"en":"A skein is a ball of coiled yarn. If it weren’t for the skein , the world would be full of tangled messes of yarn that would take hours to untangle before you could start your knitting."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41skein.mp3","us":"media/ldoce/hwd/ame/f/skein.mp3"},"examples":[{"en":"a skein of lies","cn":"一连串谎言"}],"oxford":{"phon":"skeɪn","pos":"noun","senses":[{"en":"a long piece of wool, thread or yarn that is loosely tied together","cn":"一束，一绞（毛线、线或纱）","ex":{"en":"Sally held the skein of wool while her mother wound it into a ball.","cn":"莎莉拿着一团羊毛，而她的母亲则把它卷成一个球。"}}]}},"skyrocket":{"collins":{"senses":[{"pos":"VERB 动词","cn":"剧增;猛涨;猛升","en":"If prices or amounts skyrocket, they suddenly increase by a very large amount.","ex":{"en":"Production has dropped while prices and unemployment have skyrocketed.","cn":"物价和失业率猛涨的同时，生产却下降了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a price or an amount skyrockets, it greatly increases very quickly","cn":"急升﹐猛升﹐激增﹐猛涨"}]},"vocab":{"pos":"n v","senses":[{"en":"When something skyrockets , it shoots up. Immediately after the Winter Olympics, interest in ice skating, bobsledding, and curling tends to skyrocket , or increase suddenly and dramatically."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41skyrocket.mp3","us":"media/ldoce/hwd/ame/6/skyrocket1.mp3"},"examples":[{"en":"The trade deficit has skyrocketed.","cn":"贸易逆差已经急剧增长。"},{"en":"skyrocketing inflation","cn":"飙升的通货膨胀率"}],"oxford":{"phon":"ˈskaɪrɒkɪt","pos":"verb","senses":[{"en":"to rise quickly to a very high level","cn":"飞涨；猛涨","ex":{"en":"Wages and prices have skyrocketed.","cn":"工资和物价飞涨。"}}]}},"skincare":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things that you do in order to improve the condition of your skin, especially the skin on your face","cn":"皮肤护理〔尤指脸部皮肤护理〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41skincare.mp3","us":"media/ldoce/hwd/ame/2/ld41skincare.mp3"},"examples":[{"en":"expensive skincare products","cn":"昂贵的护肤产品"}],"oxford":{"phon":"ˈskɪnkeə(r)","pos":"noun","senses":[{"en":"the use of creams and special products to look after your skin","cn":"皮肤护理；护肤"}]}},"skint":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不名一文的;身无分文的","en":"If you say that you are skint, you mean that you have no money.","ex":{"en":"I'm skint! Lend us a tenner.","cn":"我一个子儿也没有了，借我们 10 英镑吧。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having no money or very little money to spend at the moment","cn":""},{"en":"having no money at the moment","cn":""},{"en":"not having enough money at the moment","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/skint0205.mp3","us":"media/ldoce/hwd/ame/3/ld41skint.mp3"},"examples":[{"en":"I’m skint at the moment.","cn":"我现在身无分文。"}],"oxford":{"phon":"skɪnt","pos":"adjective","senses":[{"en":"having no money","cn":"没钱；不名一文","ex":{"en":"I can’t go out tonight—I’m skint.","cn":"今晚我不能出去——我很穷。"}}]}},"skepticism":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the American spelling of scepticism scepticism","cn":"的美式拼法"}]},"vocab":{"pos":"n","senses":[{"en":"Skepticism is doubt about something — you're just not convinced or can't totally believe it. You should view your 4-foot tall brother's claims that he can slam dunk a basketball with a lot of skepticism ."}]},"media":{"uk":"media/ldoce/hwd/bre/e/skepticism0205.mp3","us":"media/ldoce/hwd/ame/9/skepticism.mp3"},"examples":[{"en":"Such claims should be regarded with a certain amount of skepticism.","cn":"对这样的说法，大可不必全信。"}],"oxford":{"phon":"ˈskeptɪsɪzəm","pos":"noun","senses":[{"en":"an attitude of doubting that claims or statements are true or that something will happen","cn":"怀疑态度；怀疑主义","ex":{"en":"Such claims should be regarded with a certain amount of skepticism.","cn":"对这样的说法，大可不必全信。"}}]}},"skittle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(九柱戏的)木柱","en":"A skittle is a wooden object used as a target in the game of skittles."},{"pos":"N-UNCOUNT 不可数名词","cn":"九柱戏;撞柱游戏","en":"Skittles is a game in which players try to knock over as many skittles as they can out of a group of nine by rolling a ball at them."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a British game in which a player tries to knock down objects shaped like bottles by rolling a ball at them 〔","cn":"英国的〕撞柱戏﹐九柱戏〔沿球道以球击倒瓶状木柱的游戏〕"},{"en":"one of the objects you roll the ball at in the game of skittles 〔","cn":"撞柱戏用的〕木柱"}]},"media":{"uk":"media/ldoce/hwd/bre/2/skittle0205.mp3","us":"media/ldoce/hwd/ame/2/amelasdeskittle.mp3"},"oxford":{"phon":"ˈskɪtl","pos":"noun","senses":[{"en":"a wooden or plastic object used in the game of skittles","cn":"（滚球撞柱游戏的）木柱，塑料柱","g":"[countable]"},{"en":"(in Britain) a game in which players roll a ball at nine skittles and try to knock over as many of them as possible","cn":"（英国）滚球撞柱游戏","g":"[uncountable]"}]}},"sky-high":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(价格)极高的，昂贵的;(信心)高昂的，十足的","en":"If you say that prices or confidence are sky-high, you are emphasizing that they are at a very high level.","ex":{"en":"Christie said: 'My confidence is sky high.'","cn":"克丽丝蒂说：“我现在信心十足。”"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely high","cn":"极高的"},{"en":"to destroy something completely with an explosion","cn":"把某物炸得粉碎"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41sky-high.mp3","us":"media/ldoce/hwd/ame/7/ld41sky-high.mp3"},"examples":[{"en":"After the election, prices went sky-high.","cn":"选举后，物价飞涨。"},{"en":"His confidence is still sky-high.","cn":"他依旧信心十足。"}],"oxford":{"phon":"ˌskaɪ ˈhaɪ","pos":"adverb","senses":[{"en":"to a level that is very high or too high","cn":"极高的；太高的","ex":{"en":"After the election, prices went sky-high.","cn":"选举后，物价飞涨。"}},{"en":"very high; too high","cn":"极高的；太高的","ex":{"en":"His confidence is still sky-high.","cn":"他依旧信心十足。"},"pos":"adjective"}]}},"skiffle":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(20 世纪 50 年代流行的一种用家用物品、吉他和鼓等演奏的)噪音爵士乐，即兴摇滚乐","en":"Skiffle is a type of music, popular in the 1950s, played by a small group using household objects as well as guitars and drums."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of popular music played in the 1950s and often using instruments made by the musicians themselves","cn":"噪音爵士乐﹐史基佛音乐〔20世纪50年代的一种流行音乐﹐其乐器常由演奏者自制〕"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41skiffle.mp3","us":"media/ldoce/hwd/ame/a/ld41skiffle.mp3"},"oxford":{"phon":"ˈskɪfl","pos":"noun","senses":[{"en":"a type of music popular in the 1950s, that was a mixture of jazz and folk music","cn":"即兴摇滚乐（流行于 20 世纪 50 年代，结合了爵士乐和民间音乐）"}]}},"skydiving":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(延缓张伞的)跳伞运动，特技跳伞","en":"Skydiving is the sport of jumping out of an aeroplane and falling freely through the air before opening your parachute."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the sport of jumping from a plane and falling through the sky before opening a parachute 〔","cn":"延缓张伞的〕特技跳伞运动﹐高空跳水式跳伞"}]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeskydiving.mp3","us":"media/ldoce/hwd/ame/4/skydiving.mp3","img":["media/thumb/skydiving.jpg"]},"examples":[{"en":"to go skydiving","cn":"进行特技跳伞"}],"oxford":{"phon":"ˈskaɪdaɪvɪŋ","pos":"noun","senses":[{"en":"a sport in which you jump from a plane and fall for as long as you safely can before opening your parachute","cn":"延缓张伞跳伞运动；特技跳伞运动","ex":{"en":"to go skydiving","cn":"进行特技跳伞"}}]}},"skulduggery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"欺诈;诡诈;舞弊;搞阴谋","en":"Skulduggery is behaviour in which someone acts in a dishonest way in order to achieve their aim.","ex":{"en":"...accusations of political skulduggery.","cn":"指控其搞政治阴谋"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"secretly dishonest or illegal activity – also used humorously","cn":"阴谋诡计﹐花招﹔欺诈〔亦作幽默用法〕"}]},"vocab":{"pos":"n","senses":[{"en":"Skulduggery is dishonest words that are meant to trick people, like your brother's fast-talking that leaves you doing all of his chores and your own, plus giving him your allowance. He's a master of skulduggery ."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41skulduggery.mp3","us":"media/ldoce/hwd/ame/9/laadskulduggery.mp3"},"oxford":{"phon":"skʌlˈdʌɡəri","pos":"noun","senses":[{"en":"dishonest behaviour or activities","cn":"阴谋诡计；花招；欺骗"}]}},"skeletal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"骨骼的;骸骨的","en":"Skeletal means relating to the bones in your body.","ex":{"en":"...the skeletal remains of seven adults.","cn":"7 具成人遗骸"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"骨瘦如柴的;皮包骨头的","en":"A skeletal person is so thin that you can see their bones through their skin.","ex":{"en":"...a hospital filled with skeletal children.","cn":"住满了骨瘦如柴的儿童的医院"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"框架的;最基本的","en":"Something that is skeletal has been reduced to its basic structure.","ex":{"en":"Passenger services can best be described as skeletal.","cn":"对乘客的服务已经少到不能再少。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having little fat on your body","cn":""},{"en":"thin in an attractive way","cn":""},{"en":"thin in an attractive and graceful way – used especially about parts of the body, and used especially about women","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41skeletal.mp3","us":"media/ldoce/hwd/ame/2/skeletal.mp3"},"examples":[{"en":"He has written only a skeletal plot for the book so far.","cn":"那本书他目前只写了一个情节梗概。"},{"en":"skeletal figures dressed in rags","cn":"衣衫褴褛、骨瘦如柴的人"}],"oxford":{"phon":"ˈskelətl","pos":"adjective","senses":[{"en":"connected with the skeleton of a person or an animal","cn":"骨骼的","lab":"specialist","ex":{"en":"Skeletal remains of the earliest dinosaurs are rare.","cn":"最早的恐龙骨骼遗骸非常罕见。"}},{"en":"looking like a skeleton","cn":"骨瘦如柴的","ex":{"en":"skeletal figures dressed in rags","cn":"衣衫褴褛、骨瘦如柴的人"}},{"en":"that exists only in a basic form, as an outline","cn":"梗概的；提纲性的；提要性的；轮廓的","ex":{"en":"He has written only a skeletal plot for the book so far.","cn":"那本书他目前只写了一个情节梗概。"}}]}},"sketchbook":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"素描册;写生簿","en":"A sketchbook is a book of plain paper for drawing on."}]},"oxford":{"phon":"ˈsketʃbʊk","pos":"noun","senses":[{"en":"a book of sheets of paper for drawing on","cn":"素描簿；速写册；写生本","ex":{"en":"She took out her sketchbook and made some drawings of Arthur’s head.","cn":"她拿出素描本，画了一些亚瑟的头像。"}}]}},"skin-tight":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(衣服)紧身的","en":"Skin-tight clothes fit very tightly so that they show the shape of your body.","ex":{"en":"...the youth with the slicked down hair and skin-tight trousers.","cn":"头发油光发亮、穿着紧身裤的年轻人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"skin-tight clothes fit tightly against your body 〔","cn":"衣服〕紧身的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41skin-tight.mp3","us":"media/ldoce/hwd/ame/9/skin-tight.mp3"},"examples":[{"en":"skin-tight jeans","cn":"紧身牛仔裤"}]},"skywards":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"up into the sky or towards the sky","cn":"向着天空﹔朝向天空"}]},"media":{"uk":"media/ldoce/hwd/bre/b/skywards0205.mp3","us":"media/ldoce/hwd/ame/1/ld41skywards.mp3"},"examples":[{"en":"The rocket soared skywards.","cn":"火箭呼啸着朝天上飞去。"},{"en":"She pointed skywards.","cn":"她指向天空。"}],"oxford":{"phon":"ˈskaɪwədz","pos":"adverb","senses":[{"en":"towards the sky; up into the sky","cn":"向天空；朝天空","ex":{"en":"She pointed skywards.","cn":"她指向天空。"}}]}},"skitter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"滑行;疾行;轻轻掠过","en":"If something skitters, it moves about very lightly and quickly.","ex":{"en":"The rats skittered around them in the drains and under the floorboards","cn":"无论是下水道里，还是地板下面，都有许多耗子绕着它们蹿来蹿去。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move very quickly and lightly, like a small animal 〔","cn":"像小动物那样〕轻快地跑"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41skitter.mp3","us":"media/ldoce/hwd/ame/9/skitter.mp3"},"examples":[{"en":"Something skittered across the alley.","cn":"有个东西轻快地跑过小巷。"}],"oxford":{"phon":"ˈskɪtə(r)","pos":"verb","senses":[{"en":"to run or move very quickly and lightly","cn":"轻捷地跑；轻快地动"}]}},"skylark":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"云雀","en":"A skylark is a small brown bird that sings while flying high above the ground."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small bird that sings while flying high in the sky","cn":"云雀"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41skylark.mp3","us":"media/ldoce/hwd/ame/c/laadskylark.mp3"},"oxford":{"phon":"ˈskaɪlɑːk","pos":"noun","senses":[{"en":"a small bird that sings while it flies high up in the sky","cn":"云雀"}]}},"skirmish":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小规模战斗;接触战","en":"A skirmish is a minor battle.","ex":{"en":"Border skirmishes between India and Pakistan were common.","cn":"印度和巴基斯坦边境上常常发生小规模战斗。"}},{"pos":"V-RECIP 相互动词","cn":"发生小冲突;进行小规模战斗;打斗","en":"If people skirmish, they fight.","ex":{"en":"They were skirmishing close to the minefield now","cn":"他们当时正在雷区附近交火。"}},{"pos":"N-COUNT 可数名词","cn":"小争执;口角;争论;冲突","en":"A skirmish is a short, sharp argument.","ex":{"en":"This difference in approach has led to several political skirmishes.","cn":"这种方式上的差异已经导致了几场政治冲突。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which there is fighting between countries or opposing groups within a country, with large numbers of soldiers and weapons","cn":""},{"en":"a situation in which there is fighting or a war – used especially in news reports","cn":""},{"en":"a situation in which people or groups fight each other and try to kill each other","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A skirmish is a small fight — more a dust-up than a full-out battle — and it can refer to a physical fight or just a battle of words. It is definitely confrontational, though."}]},"collocations":{"phrases":["ADJ. little, minor | border","SKIRMISH + VERB break out, take place Minor skirmishes broke out all along the border.","PREP. in a/the ~ He was killed in a border skirmish. | ~ between skirmishes between the police and guerillas | ~ over a skirmish over bounda"]},"media":{"uk":"media/ldoce/hwd/bre/6/skirmish0205.mp3","us":"media/ldoce/hwd/ame/5/skirmish1.mp3"},"examples":[{"en":"There are reports of skirmishing along the border.","cn":"有报道称在边界一带发生了小规模冲突。"},{"en":"The young soldier was killed in a skirmish with government troops.","cn":"这名年轻士兵在和政府军的一次小冲突中丧生。"}],"oxford":{"phon":"ˈskɜːmɪʃ","pos":"noun","senses":[{"en":"a short fight between small groups of soldiers, etc., especially one that is not planned","cn":"小规模战斗；小冲突；（尤指）遭遇战","ex":{"en":"Several people were killed in skirmishes during the night.","cn":"夜间的小规模冲突中造成多人死亡。"}},{"en":"a short argument, especially between political opponents","cn":"（尤指政治上对立双方的）小争执，小争论","ex":{"en":"a skirmish between the two party leaders","cn":"两党领导人间的摩擦。"}},{"en":"to take part in a short fight or argument","cn":"发生小规模战斗（或冲突、争执）","ex":{"en":"The patrol skirmished with the enemy for several hours.","cn":"巡逻队与敌人打了数小时的遭遇战。"},"pos":"verb"}]}},"skinflint":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"吝啬鬼;守财奴","en":"If you describe someone as a skinflint, you are saying that they are a mean person who hates spending money."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who hates spending money, and tries to spend as little as possible, especially someone who stores their money in a secret place","cn":""},{"en":"someone who hates to spend or give money","cn":""},{"en":"someone who dislikes spending money, and does not care if they behave in an unreasonable way to avoid spending it","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A skinflint is someone who only shops at bargain stores, never orders dessert, and in general hates spending money. It's not a nice word, so if you're trying to compliment someone, better to call them \"thrifty\" or \"frugal.\""}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41skinflint.mp3","us":"media/ldoce/hwd/ame/3/skinflint.mp3"},"oxford":{"phon":"ˈskɪnflɪnt","pos":"noun","senses":[{"en":"a person who does not like spending money","cn":"吝啬鬼；铁公鸡"}]}},"skateboarder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"玩滑板的人","en":"A skateboarder is someone who rides on a skateboard."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short board with two small wheels at each end, which you can stand on and ride for fun or as a sport","cn":""}]},"media":{"img":["media/ldoce/img/skateboard.jpg"],"uk":"media/ldoce/hwd/bre/f/skateboard0205.mp3","us":"media/ldoce/hwd/ame/c/skateboard.mp3"},"oxford":{"phon":"ˈskeɪtbɔːdə(r)","pos":"noun","senses":[{"en":"a person who rides on a skateboard","cn":"滑（滑板）","ex":{"en":"a group of young skateboarders","cn":"一群年轻的滑板运动员"}}]}},"skydiver":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"特技跳伞者","en":"A skydiver is someone who goes skydiving."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the sport of jumping from a plane and falling through the sky before opening a parachute","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeskydiving.mp3","us":"media/ldoce/hwd/ame/4/skydiving.mp3"},"oxford":{"phon":"ˈskaɪdaɪvə(r)","pos":"noun","senses":[{"en":"a person who takes part in the sport of skydiving","cn":"跳伞运动员：参加跳伞运动的人"}]}},"sketch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"草图;略图;素描","en":"A sketch is a drawing that is done quickly without a lot of details. Artists often use sketches as a preparation for a more detailed painting or drawing.","ex":{"en":"...a sketch of a soldier by Orpen.","cn":"奥彭所画的一幅士兵素描"}},{"pos":"VERB 动词","cn":"为…画素描","en":"If you sketch something, you make a quick, rough drawing of it.","ex":{"en":"Clare and David Astor are sketching a view of far Spanish hills","cn":"克莱尔和戴维·阿斯特正在画远处西班牙山峦的风景素描。"}},{"pos":"N-COUNT 可数名词","cn":"概略描述;简述","en":"A sketch of a situation, person, or incident is a brief description of it without many details.","ex":{"en":"...thumbnail sketches of heads of state and political figures","cn":"对国家元首和政治人物的简略叙述"}},{"pos":"VERB 动词","cn":"概述;简述","en":"If you sketch a situation or incident, you give a short description of it, including only the most important facts.","ex":{"en":"Cross sketched the story briefly, telling the facts just as they had happened.","cn":"克罗斯简要地叙述了事情的经过，把当时发生的情况一五一十地说了一遍。"}},{"pos":"N-COUNT 可数名词","cn":"(通常指喜剧节目中的)幽默短剧","en":"A sketch is a short humorous piece of acting, usually forming part of a comedy show.","ex":{"en":"...a five-minute sketch about a folk singer.","cn":"刻画一位民歌手的 5 分钟幽默短剧"}},{"pos":"","cn":"","en":"相关词组：sketch in sketch out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a picture drawn with a pencil, pen, crayon etc","cn":""},{"en":"a drawing that is done quickly and has few details","cn":""},{"en":"a shape or pattern that you draw when you are bored or thinking about other things","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A sketch is a rough or brief outline of something. If you hand in a sketch , instead of your full paper, don't expect to get a very high grade!"}]},"collocations":{"phrases":["ADJ. lightning, quick | rough | preliminary, preparatory | charcoal, ink, pencil, watercolour","VERB + SKETCH do, draw, make","SKETCH + NOUN book, pad | map | plan","PREP. in a/the ~ The family house appears in several of her sketches. | ~ by a series of sketches by John Constable | ~ for to make a sketch","ADJ. brief, thumbnail The talk began with a thumbnail sketch of the political situation at that time. | biographical, character","VERB + SKETCH give sb","PREP. ~ of He gave us character sketches of all his eccentric relations. 3 short comic scene","ADJ. short | comic, satirical"]},"media":{"uk":"media/ldoce/hwd/bre/c/sketch_v0205.mp3","us":"media/ldoce/hwd/ame/f/sketch1.mp3"},"examples":[{"en":"She drew a sketch map of the area to show us the way.","cn":"她画了一幅这个地区的略图，用来给我们指路。"},{"en":"The drama group did a sketch about a couple buying a new car.","cn":"剧社上演了一出夫妻二人买新车的短剧。"}],"oxford":{"phon":"sketʃ","pos":"noun","senses":[{"en":"a simple picture that is drawn quickly and does not have many details","cn":"素描；速写；草图","lab":"US English","ex":{"en":"The artist is making sketches for his next painting.","cn":"画家正为他的下一幅作品画素描。"}},{"en":"a short funny scene on television, in the theatre, etc.","cn":"幽默短剧；小品","ex":{"en":"The drama group did a sketch about a couple buying a new car.","cn":"剧社上演了一出夫妻二人买新车的短剧。"}},{"en":"a short report or story that gives only basic details about something","cn":"简报；速写；概述","ex":{"en":"a biographical sketch of the prime minister","cn":"首相生平简介"}},{"en":"to make a quick drawing of somebody/something","cn":"画素描；画速写","g":"[transitive, intransitive]","ex":{"en":"He quickly sketched the view from the window.","cn":"他很快勾勒出了窗外的风景。"},"pos":"verb"},{"en":"to give a general description of something, giving only the basic facts","cn":"概述；简述","g":"[transitive]","ex":{"en":"She sketched out her plan for tackling the problem.","cn":"她简要叙述了解决问题的计划。"},"pos":"verb"}]}},"skimp":{"collins":{"senses":[{"pos":"VERB 动词","cn":"草率地做;马马虎虎地做;节俭使用;节省","en":"If you skimp on something, you use less time, money, or material for it than you really need, so that the result is not good enough.","ex":{"en":"Many families must skimp on their food and other necessities just to meet the monthly rent.","cn":"就为了交齐每月的租金，许多家庭不得不省吃俭用。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you make a film, run a business etc on a shoestring , you spend very little money on it, but it is usually a success","cn":""},{"en":"to not spend enough money on important materials, equipment etc, so that what you are doing or making is unsuccessful or of bad quality","cn":""},{"en":"if you do or make something on the cheap , you spend as little money as possible on it, so that it is often unsuccessful or of bad quality","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"The verb skimp refers to using a limited amount of something. When tomato prices are high, a cost-conscious restaurant might skimp on the amount of chopped tomatoes it puts on salads."}]},"media":{"uk":"media/ldoce/hwd/bre/3/skimp0205.mp3","us":"media/ldoce/hwd/ame/b/skimp.mp3"},"examples":[{"en":"Older people should not skimp on food or heating.","cn":"老人吃饭和取暖不应吝惜。"},{"en":"It’s vital not to skimp on staff training.","cn":"员工培训不能少﹐这一点十分重要。"}],"oxford":{"phon":"skɪmp","pos":"verb","senses":[{"en":"to try to spend less time, money, etc. on something than is really needed","cn":"节省，吝惜（时间、钱等）","ex":{"en":"Older people should not skimp on food or heating.","cn":"老人吃饭和取暖不应吝惜。"}}]}},"skulk":{"collins":{"senses":[{"pos":"VERB 动词","cn":"躲藏;潜伏;躲躲闪闪地走;鬼鬼祟祟地活动","en":"If you skulk somewhere, you hide or move around quietly because you do not want to be seen.","ex":{"en":"You, meanwhile, will be skulking in the safety of the car","cn":"与此同时，你会安全地藏在汽车里。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go somewhere where you cannot be easily found or seen","cn":""},{"en":"to go to a safe place where you can hide for a long time because you are in danger or because the police are looking for you","cn":""},{"en":"to hide from people who are trying to catch you, and to make sure you do not attract any attention until it is safe to come out","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Skulking is cowardly. It means hiding out, either because you're trying to pull something off in secret, or you're trying to get out of doing something you're supposed to be doing."}]},"media":{"uk":"media/ldoce/hwd/bre/f/skulk0205.mp3","us":"media/ldoce/hwd/ame/1/skulk.mp3"},"examples":[{"en":"There was someone skulking behind the bushes.","cn":"有人藏在灌木后面。"},{"en":"He was still skulking around outside when they left the building.","cn":"他们离开大楼时他还在外面鬼鬼祟祟的。"}],"oxford":{"phon":"skʌlk","pos":"verb","senses":[{"en":"to hide or move around secretly, especially when you are planning something bad","cn":"潜伏；偷偷摸摸地走动；鬼鬼祟祟地活动","ex":{"en":"There was someone skulking behind the bushes.","cn":"有人藏在灌木后面。"}}]}},"skylight":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(屋顶的)天窗","en":"A skylight is a window in a roof."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a window in the roof of a building 〔","cn":"屋顶的〕天窗"}]},"media":{"uk":"media/ldoce/hwd/bre/8/skylight0205.mp3","us":"media/ldoce/hwd/ame/3/skylight.mp3"},"oxford":{"phon":"ˈskaɪlaɪt","pos":"noun","senses":[{"en":"a small window in a roof","cn":"（房顶的）天窗"}]}},"skating":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the activity or sport of moving around on skates for fun or as a sport","cn":"滑冰﹐溜冰"}]},"collocations":{"phrases":["ADJ. ice, roller | figure, speed","VERB + SKATING go We used to go skating on the lake in cold winters.","SKATING + NOUN championships, event | rink | routine | world some of the skating world's leading choreographers •"]},"media":{"uk":"media/ldoce/hwd/bre/9/skating0205.mp3","us":"media/ldoce/hwd/ame/8/laadskating.mp3"},"examples":[{"en":"to go skating","cn":"去滑冰"},{"en":"We went skating in Central Park.","cn":"我们去中央公园溜冰了。"}],"oxford":{"phon":"ˈskeɪtɪŋ","pos":"noun","senses":[{"en":"the sport or activity of moving on ice on skates","cn":"滑冰；溜冰","ex":{"en":"to go skating","cn":"去滑冰"}},{"en":"the activity of moving over the ground wearing roller skates (= a type of boot with two pairs of small wheels attached to the bottom)","cn":"滑冰；溜冰"}]},"base":"skate"},"skit":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(采用模仿手法的)滑稽短剧，幽默讽刺小品","en":"A skit is a short performance in which the actors make fun of people, events, and types of literature by imitating them.","ex":{"en":"...clever skits on popular songs.","cn":"巧妙地讽刺了流行歌曲的滑稽短剧"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short humorous performance or piece of writing","cn":"滑稽短剧﹔幽默短文"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41skit.mp3","us":"media/ldoce/hwd/ame/0/skit.mp3"},"examples":[{"en":"a skit on daytime TV programmes","cn":"戏评日间电视节目的幽默短文"}],"oxford":{"phon":"skɪt","pos":"noun","senses":[{"en":"a short piece of humorous writing or a performance that makes fun of somebody/something by copying them","cn":"幽默短文，滑稽短剧，幽默讽刺小品（常用模仿手法）","ex":{"en":"a skit on daytime TV programmes","cn":"戏评日间电视节目的幽默短文"}}]}},"skeptic":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the American spelling of sceptic sceptic","cn":"的美式拼法"}]},"vocab":{"pos":"n","senses":[{"en":"A skeptic is a doubter. The one who can't be convinced. The guy who's ready to poke holes in the most brilliant argument you've ever made."}]},"media":{"uk":"media/ldoce/hwd/bre/a/skeptic0205.mp3","us":"media/ldoce/hwd/ame/0/skeptic.mp3"},"oxford":{"phon":"ˈskeptɪk","pos":"noun","senses":[{"en":"a person who usually doubts that claims or statements are true, especially those that other people believe in","cn":"惯持怀疑态度的人；怀疑论者","ex":{"en":"I am a born skeptic.","cn":"我是一个天生的怀疑论者。"}}]}},"skip":{"collins":{"senses":[{"pos":"VERB 动词","cn":"跳跃;蹦跳","en":"If you skip along, you move almost as if you are dancing, with a series of little jumps from one foot to the other.","ex":{"en":"They saw the man with a little girl skipping along behind him","cn":"他们看见那个男人身后还跟着一个蹦蹦跳跳的小姑娘。"}},{"pos":"VERB 动词","cn":"跳绳","en":"When someone skips, they jump up and down over a rope which they or two other people are holding at each end and turning round and round. In American English, you say that someone skips rope .","ex":{"en":"Outside, children were skipping and singing a rhyme","cn":"外面孩子们一边跳绳一边唱着歌。"}},{"pos":"VERB 动词","cn":"不做，不参加(常做或大多人都做的事)","en":"If you skip something that you usually do or something that most people do, you decide not to do it.","ex":{"en":"It is important not to skip meals","cn":"每顿饭都要吃，这一点非常重要。"}},{"pos":"VERB 动词","cn":"遗漏;略过","en":"If you skip or skip over a part of something you are reading or a story you are telling, you miss it out or pass over it quickly and move on to something else.","ex":{"en":"You might want to skip the exercises in this chapter","cn":"你们也许想跳过这一章的练习。"}},{"pos":"VERB 动词","cn":"无次序地转换","en":"If you skip from one subject or activity to another, you move quickly from one to the other although there is no obvious connection between them.","ex":{"en":"She kept up a continuous chatter, skipping from one subject to the next.","cn":"她从一个话题扯到另一个话题，一直喋喋不休。"}},{"pos":"N-COUNT 可数名词","cn":"废料桶","en":"A skip is a large, open, metal container which is used to hold and take away large unwanted items and rubbish."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to push yourself up into the air, over something etc, using your legs","cn":""},{"en":"to move forwards with little jumps between your steps, especially because you are feeling happy","cn":""},{"en":"to jump or move around on one leg","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you skip , you do a little hop from foot to foot as you move along. It's pretty common to see little kids skip down the sidewalk or across the playground."}]},"collocations":{"phrases":["ADV. lightly, nimbly | happily | along","PREP. down, up He skipped lightly up the stairs."]},"media":{"uk":"media/ldoce/hwd/bre/5/skip_n0205.mp3","us":"media/ldoce/hwd/ame/3/skip1.mp3"},"examples":[{"en":"You can skip the next chapter if you have covered the topic in class.","cn":"下一章，你要是在课堂上已经讲到了，就可以跳过。"},{"en":"The bombers skipped the country shortly after the blast.","cn":"爆炸后不久，放置炸弹的人就逃离了这个国家。"}],"oxford":{"phon":"skɪp","pos":"verb","senses":[{"en":"to move forwards lightly and quickly making a little jump with each step","cn":"蹦蹦跳跳地走","g":"[intransitive]","sc":"move with jumps","ex":{"en":"She skipped happily along beside me.","cn":"她连蹦带跳，高高兴兴地跟着我走。"}},{"en":"to jump over a rope which is held at both ends by yourself or by two other people and is passed again and again over your head and under your feet","cn":"跳绳","g":"[intransitive]","lab":"British English","sc":"jump over rope","ex":{"en":"He skips for about 20 minutes a day.","cn":"他每天跳绳大约20分钟。"}},{"en":"to not do something that you usually do or should do","cn":"不做（应做的事等）；不参加","g":"[transitive]","lab":"especially North American English","sc":"not do something","ex":{"en":"I often skip breakfast altogether.","cn":"我常常干脆不吃早饭。"}},{"en":"to leave out something that would normally be the next thing that you would do, read, etc.","cn":"跳过（正常的步骤等）；略过；漏过","g":"[transitive, intransitive]","lab":"figurative","sc":"not do something","ex":{"en":"You can skip the next chapter if you have covered the topic in class.","cn":"下一章，你要是在课堂上已经讲到了，就可以跳过。"}},{"en":"to move from one place to another or from one subject to another very quickly","cn":"快速转移；骤然转换（话题）","g":"[intransitive]","sc":"change quickly","ex":{"en":"She kept skipping from one topic of conversation to another.","cn":"她一再转换谈话的话题。"}},{"en":"to leave a place secretly or suddenly","cn":"悄悄溜走；突然离开","g":"[transitive]","lab":"informal","sc":"leave secretly","ex":{"en":"The bombers skipped the country shortly after the blast.","cn":"爆炸后不久，放置炸弹的人就逃离了这个国家。"}},{"en":"to make a flat stone jump across the surface of water","cn":"打水漂","g":"[transitive]","lab":"British English also","sc":"stones","ex":{"en":"The boys were skipping stones across the pond.","cn":"那几个男孩子用石块往水塘里打水漂。"}},{"en":"a skipping movement","cn":"蹦跳","sc":"movement","ex":{"en":"She gave a skip and a jump and was off down the street.","cn":"她一蹦一跳就顺着马路跑了。"},"pos":"noun"},{"en":"a large open container for putting old, broken building materials, rubbish, etc. in. The skip is then loaded on a lorry and taken away.","cn":"废料桶（装工地废料、垃圾等，由卡车拖走）","lab":"British English","sc":"container for waste","pos":"noun"}]}},"skull":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"头盖骨;颅骨;脑壳","en":"Your skull is the bony part of your head which encloses your brain.","ex":{"en":"Her husband was later treated for a fractured skull.","cn":"她丈夫后来接受了颅骨骨折治疗。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the bones of a person’s or animal’s head 〔","cn":"人或动物的〕颅骨﹐头骨"},{"en":"someone is unable to understand something very simple","cn":"某人的笨脑袋无法明白"}]},"collocations":{"phrases":["ADJ. thick | thin | fractured","VERB + SKULL crack, fracture","SKULL + NOUN fracture","PHRASES the back/base/front/side/top of the skull, close to the skull The soldiers' hair was cropped close to the skull. | a fracture of/to "]},"media":{"img":["media/ldoce/img/skull.jpg"],"uk":"media/ldoce/hwd/bre/f/skull0205.mp3","us":"media/ldoce/hwd/ame/4/scull.mp3"},"examples":[{"en":"( informal ) When will he get it into his thick skull that I never want to see him again!","cn":"那笨头笨脑的家伙什么时候才能明白我再也不想见他了！"},{"en":"Her skull was crammed with too many thoughts.","cn":"她脑瓜子里想法太多。"}],"oxford":{"phon":"skʌl","pos":"noun","senses":[{"en":"the bone structure that forms the head and surrounds and protects the brain","cn":"颅骨；头（盖）骨","ex":{"en":"a fractured skull","cn":"破裂的颅骨"}},{"en":"the head or the brain","cn":"脑袋；脑子；脑瓜","lab":"informal","ex":{"en":"Her skull was crammed with too many thoughts.","cn":"她脑瓜子里想法太多。"}}]}},"skateboard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"滑板","en":"A skateboard is a narrow board with wheels at each end, which people stand on and ride for pleasure."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short board with two small wheels at each end, which you can stand on and ride for fun or as a sport","cn":"滑板"}]},"media":{"img":["media/ldoce/img/skateboard.jpg"],"uk":"media/ldoce/hwd/bre/f/skateboard0205.mp3","us":"media/ldoce/hwd/ame/c/skateboard.mp3"},"examples":[{"en":"a skateboard park/ramp","cn":"滑板场/坡道"},{"en":"a skateboarding magazine","cn":"滑板运动杂志"}],"oxford":{"phon":"ˈskeɪtbɔːd","pos":"verb","senses":[{"en":"to ride on a skateboard","cn":"滑（滑板）","ex":{"en":"I used to skateboard in the streets.","cn":"我曾经在街上玩滑板。"}},{"en":"a short narrow board with small wheels at each end, which you stand on and ride as a sport","cn":"滑板","ex":{"en":"a skateboard park/ramp","cn":"滑板场／坡道"},"pos":"noun"}]}},"skewer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"串肉扦;扦子","en":"A skewer is a long metal pin which is used to hold pieces of food together during cooking."},{"pos":"VERB 动词","cn":"用扦子串住;将…叉住","en":"If you skewer something, you push a long, thin, pointed object through it.","ex":{"en":"He skewered his victim through the neck.","cn":"他用扦子刺穿了受害人的脖子。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long metal or wooden stick that is put through pieces of meat to hold them together while they are cooked 〔","cn":"金属或木质的〕串肉扦﹐烤肉扦"},{"en":"to make a hole through a piece of food, an object etc with a skewer or with some other pointed object 〔","cn":"用烤肉扦或类似东西〕把…串起来"},{"en":"to criticize someone very strongly, often in a way that other people find humorous","cn":"讽刺﹐讥讽"}]},"media":{"uk":"media/ldoce/hwd/bre/c/skewer_n0205.mp3","us":"media/ldoce/hwd/ame/5/skewer1.mp3"},"examples":[{"en":"Du Bois skewered Washington’s policies in his book, ‘The Souls of Black Folks’.","cn":"杜波依斯在他《黑人的灵魂》一书中讽刺了美国政府的政策。"}],"oxford":{"phon":"ˈskjuːə(r)","pos":"noun","senses":[{"en":"a long thin pointed piece of metal or wood that is pushed through pieces of meat, vegetables, etc. to hold them together while they are cooking, or used to test whether something is completely cooked","cn":"（烹饪用）扦子，串肉扦"},{"en":"to push a skewer or other thin pointed object through something","cn":"用扦子串住","ex":{"en":"Skewer the meat and vegetables.","cn":"将肉和蔬菜串起来。"},"pos":"verb"}]}},"sketchy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(信息)粗略的，大概的，不完全的，不充分的","en":"Sketchy information about something does not include many details and is therefore incomplete or inadequate.","ex":{"en":"Details of what actually happened are still sketchy","cn":"对于已发生事实的详细情况知道的仍然有限。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is vague is not clear because it does not provide enough details","cn":""},{"en":"something that is sketchy is not thorough or complete enough because it lacks details","cn":""},{"en":"a piece of information or a description that is thin is not detailed enough to be useful or effective","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something sketchy is incomplete: it includes the major points but lacks detail. If a political candidate avoids going into detail about her political views, you might say her platform is sketchy ."}]},"media":{"uk":"media/ldoce/hwd/bre/f/sketchy0205.mp3","us":"media/ldoce/hwd/ame/f/sketchy.mp3"},"examples":[{"en":"He gave us a very sketchy account of his visit.","cn":"他跟我们非常粗略地讲了他参观的情况。"},{"en":"sketchy notes","cn":"简略的笔记"}],"oxford":{"phon":"ˈsketʃi","pos":"adjective","senses":[{"en":"not complete or detailed and therefore not very useful","cn":"粗略的；概略的；不完备的","ex":{"en":"He gave us a very sketchy account of his visit.","cn":"他跟我们非常粗略地讲了他参观的情况。"}},{"en":"that people consider to be dishonest or bad","cn":"不诚实的；不道德的","lab":"North American English, informal，，","ex":{"en":"a sketchy neighborhood","cn":"没有诚信的街坊"}}]}},"sky-blue":{"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"天蓝色;蔚蓝","en":"Something that is sky-blue is a very pale blue in colour.","ex":{"en":"Her silk shirtdress was sky-blue, the colour of her eyes.","cn":"她一袭天蓝色的真丝衬衫式连身裙，和她的双眸颜色一样。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"bright blue, like the colour of the sky when there are no clouds","cn":"天蓝色的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41sky-blue.mp3","us":"media/ldoce/hwd/ame/4/ld41sky-blue.mp3"},"oxford":{"phon":"ˌskaɪ ˈbluː","pos":"noun","senses":[{"en":"a bright blue colour, like the colour of the sky on a clear day","cn":"天蓝色的；蔚蓝色的"},{"en":"bright blue in colour, like the sky on a clear day","cn":"天蓝色的；蔚蓝色的","pos":"adjective"}]}},"skittish":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人或动物)易激动的，易受惊的","en":"If you describe a person or animal as skittish, you mean they are easily made frightened or excited.","ex":{"en":"The declining dollar gave heart to skittish investors.","cn":"美元的衰落给总是担惊受怕的投资者们带来了信心。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没长性的;轻佻的;善变的;靠不住的","en":"Someone who is skittish does not concentrate on anything or take life very seriously.","ex":{"en":"...his relentlessly skittish sense of humour.","cn":"他那永远变化不定的幽默感"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an animal, especially a horse, that is skittish gets excited or frightened very easily 〔","cn":"动物﹐尤指马〕易激动的﹐易受惊的"},{"en":"a person who is skittish is not very serious, and their feelings, behaviour, and opinions keep changing 〔","cn":"人〕轻浮的﹐轻佻的﹔善变的"},{"en":"if people who buy share s are skittish, they are nervous and worried about them dropping in value, and might sell the shares that they own because of this 〔","cn":"购买股票者〕紧张不安的﹐担惊受怕的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you're skittish , you're unpredictable and excitable. You've probably seen skittish horses in parades — the loud noises and crowds of people make them very nervous and jumpy."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41skittish.mp3","us":"media/ldoce/hwd/ame/d/skittish.mp3"},"examples":[{"en":"skittish financial markets","cn":"变幻莫测的金融市场"},{"en":"Some skittish Wall Street investors are staying away from the market.","cn":"一些患得患失的华尔街投资者不敢入市。"}],"oxford":{"phon":"ˈskɪtɪʃ","pos":"adjective","senses":[{"en":"easily excited or frightened and therefore difficult to control","cn":"易惊而难以驾驭的"},{"en":"not very serious and with ideas and feelings that keep changing","cn":"轻浮的；易变的；反复无常的"},{"en":"likely to change suddenly","cn":"说变就变的；变幻莫测的","lab":"especially North American English, business，，","ex":{"en":"skittish financial markets","cn":"变幻莫测的金融市场"}}]}},"skinless":{"lemma":"skin"},"skyline":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(建筑物在天空映衬下的)轮廓线,天际线","en":"The skyline is the line or shape that is formed where the sky meets buildings or the land.","ex":{"en":"The village church dominates the skyline.","cn":"乡村教堂在天空映衬下的轮廓非常醒目。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the shape made by hills or buildings against the sky 〔","cn":"山或建筑物在天空映衬下的〕轮廓（线）﹐天际线"}]},"collocations":{"phrases":["ADJ. dramatic | city | Hong Kong, London, etc. | northern, southern, etc.","VERB + SKYLINE form | dominate The skyline is dominated by a nuclear power station. | be silhouetted against/on, stand (out) against/on A me","PREP. above/over ~ Clouds of smoke floated over the skyline. | against the ~ the moving figures he could see against the skyline | along the"]},"media":{"uk":"media/ldoce/hwd/bre/a/skyline0205.mp3","us":"media/ldoce/hwd/ame/6/skyline.mp3"},"examples":[{"en":"the New York skyline","cn":"纽约的空中轮廓线"},{"en":"the famous New York skyline","cn":"著名的纽约天际线"}],"oxford":{"phon":"ˈskaɪlaɪn","pos":"noun","senses":[{"en":"the outline of buildings, trees, hills, etc. seen against the sky","cn":"（建筑物、树、山等在天空映衬下的）轮廓线；天际线","ex":{"en":"the New York skyline","cn":"纽约的空中轮廓线"}}]}},"skyward":{"lemma":"skywards","media":{"uk":"media/ldoce/hwd/bre/b/skywards0205.mp3","us":"media/ldoce/hwd/ame/1/ld41skywards.mp3"}},"skiing":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the sport of moving down hills, across land in the snow, or on water wearing ski s","cn":"滑雪[滑水]运动"}]},"collocations":{"phrases":["ADJ. alpine, downhill | cross-country, langlauf, Nordic | dry-slope | off-piste | freestyle | good, quality","VERB + SKIING go | have The United States has plenty of good skiing.","SKIING + NOUN holiday, trip | resort | season | equipment | facilities | slope | conditions •"]},"media":{"uk":"media/ldoce/hwd/bre/c/skiing0205.mp3","us":"media/ldoce/hwd/ame/3/laadskiing.mp3","img":["media/ldoce/img/skiing.jpg"]},"examples":[{"en":"a skiing holiday/instructor/lesson/vacation","cn":"滑雪假日/教练/课/假期"},{"en":"downhill/cross-country skiing","cn":"速降/越野滑雪"}],"oxford":{"phon":"ˈskiːɪŋ","pos":"noun","senses":[{"en":"the sport or activity of moving over snow on skis","cn":"滑雪（运动）","ex":{"en":"He also enjoys skiing and mountain biking.","cn":"他还喜欢滑雪和山地自行车。"}}]},"base":"ski"},"skid":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(车辆)侧滑，打滑;(刹车时)滑行","en":"If a vehicle skids, it slides sideways or forwards while moving, for example when you are trying to stop it suddenly on a wet road.","ex":{"en":"The car pulled up too fast and skidded on the dusty shoulder of the road","cn":"由于刹车太急，车子侧滑到了满是尘土的路肩上。"}},{"pos":"PHRASE 短语","cn":"无法挽救的;注定要失败的","en":"If you say that something is on the skids, you believe that it is out of control and certain to fail.","ex":{"en":"His career is on the skids.","cn":"他的事业每况愈下。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move smoothly over a surface while continuing to touch it","cn":""},{"en":"to slide a short distance accidentally, and fall or lose your balance slightly","cn":""},{"en":"to slide sideways or forwards in a way that is difficult to control – used especially about a moving vehicle","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Whoopsy daisy! Those new fuzzy socks make it easy to skid , or slide unexpectedly, across the wood floor."}]},"collocations":{"phrases":["VERB + SKID get into, go into The lorry went into a skid and crashed into the barrier.","SKID + NOUN mark The police examined the skid marks to see how fast the car had been travelling."]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeskid.mp3","us":"media/ldoce/hwd/ame/2/skid1.mp3"},"examples":[{"en":"The skid marks on the road showed how fast the car had been travelling.","cn":"公路上留下的滑行痕迹说明这辆车当时开得有多快。"},{"en":"Her foot skidded on the wet floor and she fell heavily.","cn":"她的脚在湿地板上一滑，重重地摔了一跤。"}],"oxford":{"phon":"skɪd","pos":"verb","senses":[{"en":"to slide forward or to one side in a way that shows a loss of control","cn":"打滑；侧滑；滑行","ex":{"en":"The car skidded on the ice and went straight into the wall.","cn":"汽车在冰上打滑，径直撞到了墙上。"}},{"en":"the movement of a vehicle when it suddenly slides to one side because you have lost control of it","cn":"侧滑；打滑；突然向一侧滑行","ex":{"en":"The motorbike went into a skid.","cn":"摩托车朝一侧滑了出去。"},"pos":"noun"},{"en":"a part that is on the bottom of some aircraft, next to the wheels, and is used for landing","cn":"（飞机的）起落橇，滑橇","ex":{"en":"the skids of a helicopter","cn":"直升机的起落橇"},"pos":"noun"}]}}});
